function Calendar({ personal = false }: { personal?: boolean }) {
  const [scope, setScope] = useState<CalendarScope>(personal ? "Personal calendar" : "Master calendar");
  const [filter, setFilter] = useState<CalendarFilter>("All");
  const [ministry, setMinistry] = useState("All ministries");
  const [role, setRole] = useState("All roles");
  const events = filterPreviewEvents(previewEvents, scope, filter, ministry, role);
  return <section className={styles.panel} aria-label="Calendar preview"><div className={styles.calendarHeading}><SectionTitle title={personal ? "My calendar" : "Calendar"} help="Master and personal calendars combine ministry, role, assignment, and sharing filters. In the live app, the server will enforce access from approved roles and event assignments; filters here use sample data only." /><label className={styles.selectLabel}>Calendar view<select value={scope} onChange={(event) => setScope(event.target.value as CalendarScope)}>{!personal && <option>Master calendar</option>}<option>Personal calendar</option></select></label></div><div className={styles.calendarControls}><div className={styles.filterGroup} role="group" aria-label="Calendar filters">{calendarFilters.map((item) => <button key={item} aria-pressed={filter === item} onClick={() => setFilter(item)}>{item}</button>)}</div><div className={styles.calendarSelects}><label className={styles.selectLabel}>Ministry<select value={ministry} onChange={(event) => setMinistry(event.target.value)}><option>All ministries</option><option>Studies</option><option>Outreach</option><option>Prayer</option></select></label><label className={styles.selectLabel}>Role<select value={role} onChange={(event) => setRole(event.target.value)}><option>All roles</option><option>Study facilitator</option><option>Men’s Forge</option><option>Serve team</option><option>Ministry leader</option><option>Prayer team</option></select></label></div></div><details className={styles.calendarAccess}><summary>How role and assignment sharing works</summary><p>Each event is visible only to people with an approved role for that ministry or to people directly assigned to it. Personal events stay private unless the member shares them. The role filter narrows this sample view; it does not grant access.</p></details><div aria-live="polite" aria-atomic="true"><p className={styles.resultCount}>{events.length + (events.length === 1 ? " sample event" : " sample events")}</p>{events.length ? <ul className={styles.agenda}>{events.map((event) => <li key={event.id}><span className={styles.eventDate}>{event.date}</span><time>{event.time}</time><div><strong>{event.title}</strong><span>{event.assigned ? "Assigned to you" : event.shared ? "Shared with your role" : "My event"}<small className={styles.eventAccess}>Roles: {event.roles.join(", ")} · Assigned: {event.assignee}</small></span></div></li>)}</ul> : <p className={styles.empty}>No sample events match these filters. Choose All or another ministry.</p>}</div><p className={styles.caption}>Design preview · sample events, roles, and assignments only</p></section>;
}

function PrayerComposer({ member, onClose, onSubmit }: { member: boolean; onClose: () => void; onSubmit: (message: string) => void }) {
  const [request, setRequest] = useState("");
  const [acknowledged, setAcknowledged] = useState(false);
  const [audience, setAudience] = useState("Prayer team only");
  const [group, setGroup] = useState("Men’s Bible study");
  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const visibility = !member ? "public after moderator review" : audience === "One accepted group" ? group : audience;
    onSubmit(`Sample only: prayer request would be shared with ${visibility}. No request was submitted or saved.`);
    onClose();
  }
  return <div className={styles.modalBackdrop} onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><form className={styles.prayerDialog} role="dialog" aria-modal="true" aria-labelledby="prayer-composer-title" onSubmit={submit}><div className={styles.eventCardTop}><div><p className={styles.eyebrow}>{member ? "Member prayer" : "Visitor prayer"}</p><h2 id="prayer-composer-title">Submit a prayer request</h2></div><button type="button" className={styles.outlineButton} onClick={onClose}>Close</button></div><p className={styles.eventDialogIntro}>{member ? "Choose who may see this request. A moderator cannot expand the audience you choose." : "Visitor requests are public-only. They stay hidden from everyone until a moderator clears them for public sharing."}</p><label className={styles.prayerField}>Prayer request<textarea value={request} onChange={(event) => setRequest(event.target.value)} rows={5} placeholder="What would you like prayer for?" required /></label>{member ? <div className={styles.prayerAudience}><label className={styles.selectLabel}>Who may see this?<select value={audience} onChange={(event) => setAudience(event.target.value)}><option>Prayer team only</option><option>One accepted group</option><option>Public after moderator review</option></select></label>{audience === "One accepted group" && <label className={styles.selectLabel}>Accepted group<select value={group} onChange={(event) => setGroup(event.target.value)}><option>Men’s Bible study</option><option>Prayer ministry</option></select></label>}<p>Moderators cannot broaden your selected audience. Public requests appear only after review.</p></div> : <label className={styles.prayerCheck}><input type="checkbox" checked={acknowledged} onChange={(event) => setAcknowledged(event.target.checked)} /><span>I understand this request may be shared publicly after moderator review.</span></label>}<div className={styles.requestActions}><button type="button" className={styles.outlineButton} onClick={onClose}>Cancel</button><button className={styles.primaryButton} type="submit" disabled={!request.trim() || (!member && !acknowledged)}>{member ? "Submit prayer request" : "Submit for review"}</button></div><p className={styles.caption}>Design preview only · nothing is sent or saved</p></form></div>;
}

function CareCheckIn({ onClose, onSubmit }: { onClose: () => void; onSubmit: (message: string) => void }) {
  const [choice, setChoice] = useState("");
  const [note, setNote] = useState("");
  const [acknowledged, setAcknowledged] = useState(false);
  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSubmit("Sample only: a care check-in would be routed to an authorized, assigned ministry leader. No information was sent or saved.");
    onClose();
  }
  return <div className={styles.modalBackdrop} onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><form className={styles.prayerDialog} role="dialog" aria-modal="true" aria-labelledby="care-checkin-title" onSubmit={submit}><div className={styles.eventCardTop}><div><p className={styles.eyebrow}>Your care matters</p><h2 id="care-checkin-title">How are you doing?</h2></div><button type="button" className={styles.outlineButton} onClick={onClose}>Close</button></div><p className={styles.eventDialogIntro}>This is a private check-in request for an authorized, assigned ministry leader. It does not appear in public Prayer &amp; Praise and does not start a member-to-member chat.</p><fieldset className={styles.careChoices}><legend>Choose what best fits today</legend>{[["doing-well", "I’m doing okay"], ["prayer", "I could use prayer"], ["follow-up", "I’d appreciate a personal check-in"]].map(([value, label]) => <label key={value}><input type="radio" name="care-choice" value={value} checked={choice === value} onChange={() => setChoice(value)}/><span>{label}</span></label>)}</fieldset><label className={styles.prayerField}>Anything you’d like your leader to know? <span className={styles.optionalLabel}>Optional</span><textarea value={note} onChange={(event) => setNote(event.target.value)} rows={4} placeholder="Share only what you are comfortable sharing." /></label><label className={styles.prayerCheck}><input type="checkbox" checked={acknowledged} onChange={(event) => setAcknowledged(event.target.checked)}/><span>I understand this would be visible only to authorized leaders assigned to care for me.</span></label><div className={styles.requestActions}><button type="button" className={styles.outlineButton} onClick={onClose}>Cancel</button><button className={styles.primaryButton} type="submit" disabled={!choice || !acknowledged}>Request a check-in</button></div><p className={styles.caption}>Design preview only · no response or note is sent or saved</p></form></div>;
}

